class Solution {
    int currVal = 0;
    int currCount = 0;
    int maxCount = 0;
    bool first = true;
    vector<int> modes;

    void inorder(TreeNode* node) {
        if (!node) return;
        inorder(node->left);
        if (first || node->val != currVal) {
            currVal = node->val;
            currCount = 1;
            first = false;
        } else {
            currCount++;
        }
        if (currCount > maxCount) {
            maxCount = currCount;
            modes = {currVal};
        } else if (currCount == maxCount) {
            modes.push_back(currVal);
        }
